     1→const { Task, Subtask } = require('../models');
     2→
     3→const getTasks = async (req, res) => {
     4→  try {
     5→    const tasks = await Task.findAll({
     6→      where: { project_id: req.params.projectId },
     7→      include: [{ model: Subtask, as: 'subtasks' }],
     8→      order: [['created_at', 'ASC']],
     9→    });
    10→    res.json(tasks);
    11→  } catch (error) {
    12→    res.status(500).json({ message: 'Error al obtener tareas', error: error.message });
    13→  }
    14→};
    15→
    16→const getTask = async (req, res) => {
    17→  try {
    18→    const task = await Task.findOne({
    19→      where: { id: req.params.id, project_id: req.params.projectId },
    20→      include: [{ model: Subtask, as: 'subtasks', order: [['created_at', 'ASC']] }],
    21→    });
    22→    if (!task) return res.status(404).json({ message: 'Tarea no encontrada' });
    23→    res.json(task);
    24→  } catch (error) {
    25→    res.status(500).json({ message: 'Error al obtener tarea', error: error.message });
    26→  }
    27→};
    28→
    29→const createTask = async (req, res) => {
    30→  try {
    31→    const { title, description, priority, status, estimated_hours } = req.body;
    32→    const task = await Task.create({
    33→      project_id: req.params.projectId,
    34→      title,
    35→      description,
    36→      priority: priority || 'media',
    37→      status: status || 'backlog',
    38→      estimated_hours: estimated_hours || 0,
    39→    });
    40→    res.status(201).json(task);
    41→  } catch (error) {
    42→    if (error.name === 'SequelizeValidationError') {
    43→      return res.status(400).json({ message: 'Error de validación', errors: error.errors.map(e => e.message) });
    44→    }
    45→    res.status(500).json({ message: 'Error al crear tarea', error: error.message });
    46→  }
    47→};
    48→
    49→const updateTask = async (req, res) => {
    50→  try {
    51→    const task = await Task.findOne({
    52→      where: { id: req.params.id, project_id: req.params.projectId },
    53→    });
    54→    if (!task) return res.status(404).json({ message: 'Tarea no encontrada' });
    55→    const { title, description, priority, status, estimated_hours } = req.body;
    56→    await task.update({ title, description, priority, status, estimated_hours });
    57→    res.json(task);
    58→  } catch (error) {
    59→    if (error.name === 'SequelizeValidationError') {
    60→      return res.status(400).json({ message: 'Error de validación', errors: error.errors.map(e => e.message) });
    61→    }
    62→    res.status(500).json({ message: 'Error al actualizar tarea', error: error.message });
    63→  }
    64→};
    65→
    66→const deleteTask = async (req, res) => {
    67→  try {
    68→    const task = await Task.findOne({
    69→      where: { id: req.params.id, project_id: req.params.projectId },
    70→    });
    71→    if (!task) return res.status(404).json({ message: 'Tarea no encontrada' });
    72→    await task.destroy();
    73→    res.json({ message: 'Tarea eliminada exitosamente' });
    74→  } catch (error) {
    75→    res.status(500).json({ message: 'Error al eliminar tarea', error: error.message });
    76→  }
    77→};
    78→
    79→module.exports = { getTasks, getTask, createTask, updateTask, deleteTask };
    80→

