    17→    <div
    18→      style={{
    19→        backgroundColor: '#0f172a',
    20→        border: '1px solid #334155',
    21→        borderRadius: '8px',
    22→        padding: '0.875rem',
    23→        cursor: 'pointer',
    24→        transition: 'all 0.15s ease',
    25→        userSelect: 'none',
    26→      }}
    27→      onClick={onClick}
    28→      onMouseEnter={e => {
    29→        e.currentTarget.style.borderColor = '#818cf8';
    30→        e.currentTarget.style.backgroundColor = '#111827';
    31→      }}
    32→      onMouseLeave={e => {
    33→        e.currentTarget.style.borderColor = '#334155';
    34→        e.currentTarget.style.backgroundColor = '#0f172a';
    35→      }}
    36→    >
    37→      {/* Title row */}
    38→      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '0.5rem' }}>
