    40→          color: '#e2e8f0',
    41→          fontSize: '0.875rem',
    42→          fontWeight: 500,
    43→          flex: 1,
    44→          lineHeight: '1.4',
    45→        }}>
    46→          {task.title}
    47→        </span>
    48→        <div
    49→          style={{ display: 'flex', gap: '2px', marginLeft: '0.5rem', flexShrink: 0 }}
    50→          onClick={e => e.stopPropagation()}
    51→        >
    52→          <Button
    53→            icon="pi pi-pencil"
    54→            size="small"
    55→            text
    56→            rounded
    57→            severity="secondary"
    58→            onClick={onEdit}
    59→            style={{ width: '1.6rem', height: '1.6rem' }}
    60→            tooltip="Editar"
    61→            tooltipOptions={{ position: 'top' }}
    62→          />
    63→          <Button
    64→            icon="pi pi-trash"
    65→            size="small"
    66→            text
    67→            rounded
    68→            severity="danger"
    69→            onClick={onDelete}
    70→            style={{ width: '1.6rem', height: '1.6rem' }}
    71→            tooltip="Eliminar"
    72→            tooltipOptions={{ position: 'top' }}
    73→          />
    74→        </div>
    75→      </div>
    76→
    77→      {/* Description */}
    78→      {task.description && (
    79→        <p style={{
    80→          margin: '0 0 0.625rem',
    81→          color: '#64748b',
    82→          fontSize: '0.8rem',
    83→          lineHeight: '1.4',
    84→          display: '-webkit-box',
    85→          WebkitLineClamp: 2,
    86→          WebkitBoxOrient: 'vertical',
    87→          overflow: 'hidden',
    88→        }}>
    89→          {task.description}
    90→        </p>
    91→      )}
    92→
    93→      {/* Subtasks progress */}
    94→      {subtaskCount > 0 && (
    95→        <div style={{ marginBottom: '0.625rem' }}>
    96→          <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '3px' }}>
    97→            <span style={{ color: '#64748b', fontSize: '0.75rem' }}>Subtareas</span>
    98→            <span style={{ color: '#64748b', fontSize: '0.75rem' }}>{completedSubtasks}/{subtaskCount}</span>
    99→          </div>
   100→          <div style={{ backgroundColor: '#1e293b', borderRadius: '3px', height: '4px', overflow: 'hidden' }}>
   101→            <div style={{
   102→              width: `${(completedSubtasks / subtaskCount) * 100}%`,
   103→              height: '100%',
   104→              backgroundColor: '#818cf8',
   105→              borderRadius: '3px',
   106→              transition: 'width 0.3s',
   107→            }}></div>
   108→          </div>
   109→        </div>
   110→      )}
   111→
   112→      {/* Footer */}
   113→      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: '0.5rem' }}>
   114→        <Tag
   115→          value={priority.label}
   116→          severity={priority.severity}
   117→          icon={`pi ${priority.icon}`}
   118→          style={{ fontSize: '0.7rem', padding: '2px 6px' }}
   119→        />
   120→        {parseFloat(task.estimated_hours) > 0 && (
   121→          <span style={{ color: '#64748b', fontSize: '0.75rem' }}>
   122→            <i className="pi pi-clock" style={{ marginRight: '3px', fontSize: '0.7rem' }}></i>
   123→            {task.estimated_hours}h
   124→          </span>
   125→        )}
   126→      </div>
   127→    </div>
   128→  );
   129→};
   130→
   131→export default TaskCard;
