     3→const getProjects = async (req, res) => {
     4→  try {
     5→    const projects = await Project.findAll({
     6→      include: [{ model: Task, as: 'tasks', attributes: ['id', 'status'] }],
     7→      order: [['created_at', 'DESC']],
     8→    });
     9→    res.json(projects);
    10→  } catch (error) {
    11→    res.status(500).json({ message: 'Error al obtener proyectos', error: error.message });
    12→  }
    13→};
    14→
    15→const getProject = async (req, res) => {
    16→  try {
    17→    const project = await Project.findByPk(req.params.id, {
    18→      include: [{ model: Task, as: 'tasks', order: [['created_at', 'ASC']] }],
    19→    });
    20→    if (!project) return res.status(404).json({ message: 'Proyecto no encontrado' });
    21→    res.json(project);
    22→  } catch (error) {
    23→    res.status(500).json({ message: 'Error al obtener proyecto', error: error.message });
    24→  }
    25→};
    26→
    27→const createProject = async (req, res) => {
    28→  try {
    29→    const { name, description, deadline } = req.body;
    30→    const project = await Project.create({ name, description, deadline });
    31→    res.status(201).json(project);
    32→  } catch (error) {
    33→    if (error.name === 'SequelizeValidationError') {
    34→      return res.status(400).json({ message: 'Error de validación', errors: error.errors.map(e => e.message) });
    35→    }
    36→    res.status(500).json({ message: 'Error al crear proyecto', error: error.message });
    37→  }
    38→};
    39→
    40→const updateProject = async (req, res) => {
    41→  try {
    42→    const project = await Project.findByPk(req.params.id);
    43→    if (!project) return res.status(404).json({ message: 'Proyecto no encontrado' });
    44→    const { name, description, deadline, status } = req.body;
    45→    await project.update({ name, description, deadline, status });
    46→    res.json(project);
    47→  } catch (error) {
    48→    if (error.name === 'SequelizeValidationError') {
    49→      return res.status(400).json({ message: 'Error de validación', errors: error.errors.map(e => e.message) });
    50→    }
    51→    res.status(500).json({ message: 'Error al actualizar proyecto', error: error.message });
    52→  }
    53→};
    54→
    55→const deleteProject = async (req, res) => {
    56→  try {
    57→    const project = await Project.findByPk(req.params.id);
    58→    if (!project) return res.status(404).json({ message: 'Proyecto no encontrado' });
    59→    await project.destroy();
    60→    res.json({ message: 'Proyecto eliminado exitosamente' });
    61→  } catch (error) {
    62→    res.status(500).json({ message: 'Error al eliminar proyecto', error: error.message });
    63→  }
    64→};
    65→
    66→module.exports = { getProjects, getProject, createProject, updateProject, deleteProject };
    67→

