     1→const Anthropic = require('@anthropic-ai/sdk');
     2→
     3→const decomposeTask = async (req, res) => {
     4→  try {
     5→    const { description, context } = req.body;
     6→
     7→    if (!description || !description.trim()) {
     8→      return res.status(400).json({ message: 'La descripción de la tarea es requerida' });
     9→    }
    10→
    11→    if (!process.env.ANTHROPIC_API_KEY) {
    12→      return res.status(500).json({ message: 'La API key de Anthropic no está configurada' });
    13→    }
    14→
    15→    const client = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY });
    16→
    17→    const systemPrompt = `Eres un experto en gestión de proyectos de software. Tu tarea es descomponer tareas complejas de desarrollo en subtareas específicas y accionables.
    18→
    19→Para cada subtarea debes proporcionar:
    20→- title: Título breve y claro (máximo 100 caracteres)
    21→- description: Descripción detallada de lo que hay que hacer
    22→- priority: Una de "alta", "media" o "baja" basada en importancia y dependencias
    23→- estimated_hours: Estimación realista en horas (número decimal, ej: 1.5)
    24→
    25→Responde ÚNICAMENTE con un array JSON válido, sin texto adicional, sin markdown, sin bloques de código.`;
    26→
    27→    const userMessage = `Descompón la siguiente tarea de desarrollo en subtareas específicas y accionables:
    28→
    29→Tarea: "${description}"${context ? `\n\nContexto del proyecto: "${context}"` : ''}
    30→
    31→Genera entre 3 y 10 subtareas según la complejidad. Asegúrate de cubrir todos los aspectos necesarios (backend, frontend, tests, documentación si aplica).`;
    32→
    33→    const message = await client.messages.create({
    34→      model: 'claude-haiku-4-5-20251001',
    35→      max_tokens: 2048,
    36→      system: systemPrompt,
    37→      messages: [{ role: 'user', content: userMessage }],
    38→    });
    39→
    40→    const content = message.content[0].text.trim();
    41→
    42→    let subtasks;
    43→    try {
    44→      const jsonMatch = content.match(/\[[\s\S]*\]/);
    45→      subtasks = jsonMatch ? JSON.parse(jsonMatch[0]) : JSON.parse(content);
    46→    } catch (parseError) {
    47→      return res.status(500).json({
    48→        message: 'Error al parsear la respuesta de la IA',
    49→        raw: content,
    50→      });
    51→    }
    52→
    53→    if (!Array.isArray(subtasks)) {
    54→      return res.status(500).json({ message: 'La IA no devolvió un formato válido' });
    55→    }
    56→
    57→    res.json({ subtasks });
    58→  } catch (error) {
    59→    if (error.status === 401) {
    60→      return res.status(401).json({ message: 'API key de Anthropic inválida' });
    61→    }
    62→    if (error.status === 429) {
    63→      return res.status(429).json({ message: 'Límite de rate de la API de Anthropic alcanzado' });
    64→    }
    65→    res.status(500).json({ message: 'Error al llamar al servicio de IA', error: error.message });
    66→  }
    67→};
    68→
    69→module.exports = { decomposeTask };
    70→

