     1→const { Subtask } = require('../models');
     2→
     3→const getSubtasks = async (req, res) => {
     4→  try {
     5→    const subtasks = await Subtask.findAll({
     6→      where: { task_id: req.params.taskId },
     7→      order: [['created_at', 'ASC']],
     8→    });
     9→    res.json(subtasks);
    10→  } catch (error) {
    11→    res.status(500).json({ message: 'Error al obtener subtareas', error: error.message });
    12→  }
    13→};
    14→
    15→const createSubtask = async (req, res) => {
    16→  try {
    17→    const { title, description, priority, estimated_hours } = req.body;
    18→    const subtask = await Subtask.create({
    19→      task_id: req.params.taskId,
    20→      title,
    21→      description,
    22→      priority: priority || 'media',
    23→      estimated_hours: estimated_hours || 0,
    24→    });
    25→    res.status(201).json(subtask);
    26→  } catch (error) {
    27→    if (error.name === 'SequelizeValidationError') {
    28→      return res.status(400).json({ message: 'Error de validación', errors: error.errors.map(e => e.message) });
    29→    }
    30→    res.status(500).json({ message: 'Error al crear subtarea', error: error.message });
    31→  }
    32→};
    33→
    34→const createBulkSubtasks = async (req, res) => {
    35→  try {
    36→    const { subtasks } = req.body;
    37→    if (!Array.isArray(subtasks) || subtasks.length === 0) {
    38→      return res.status(400).json({ message: 'Se requiere un array de subtareas' });
    39→    }
    40→    const created = await Subtask.bulkCreate(
    41→      subtasks.map(s => ({
    42→        task_id: req.params.taskId,
    43→        title: s.title,
    44→        description: s.description || '',
    45→        priority: s.priority || 'media',
    46→        estimated_hours: s.estimated_hours || 0,
    47→      }))
    48→    );
    49→    res.status(201).json(created);
    50→  } catch (error) {
    51→    res.status(500).json({ message: 'Error al crear subtareas', error: error.message });
    52→  }
    53→};
    54→
    55→const updateSubtask = async (req, res) => {
    56→  try {
    57→    const subtask = await Subtask.findOne({
    58→      where: { id: req.params.id, task_id: req.params.taskId },
    59→    });
    60→    if (!subtask) return res.status(404).json({ message: 'Subtarea no encontrada' });
    61→    const { title, description, priority, estimated_hours, is_completed } = req.body;
    62→    await subtask.update({ title, description, priority, estimated_hours, is_completed });
    63→    res.json(subtask);
    64→  } catch (error) {
    65→    res.status(500).json({ message: 'Error al actualizar subtarea', error: error.message });
    66→  }
    67→};
    68→
    69→const deleteSubtask = async (req, res) => {
    70→  try {
    71→    const subtask = await Subtask.findOne({
    72→      where: { id: req.params.id, task_id: req.params.taskId },
    73→    });
    74→    if (!subtask) return res.status(404).json({ message: 'Subtarea no encontrada' });
